//! Scheme parsers for non-full-pinyin input surfaces.
//!
//! Double pinyin and Zhuyin are source-embedded keyboard schemes. The
//! tables are generated by `just rust-tables` from the unmodified scripts2
//! logic at libpinyin `074a2219`, with header provenance recorded in
//! `tools/scripts2/README.md` and parser semantics in
//! `docs/findings/double-pinyin-spec.md`. The Simple Zhuyin keyboards
//! (STANDARD, IBM, GINYIEH, ETEN) and their tone tables come from
//! `src/storage/zhuyin_table.h`; the Zhuyin index — the pinned 1493-row
//! `zhuyin_index` with its shuffle and incomplete flag gating — lives in
//! [`crate::zhuyin_map`].

use crate::SyllableKey;
use crate::options::OptionBits;
use crate::zhuyin_map::VALID_ZHUYIN_TONES;
use crate::{CHEWING_ZERO_TONE, ChewingKey};

/// One parsed double-pinyin key: a full-pinyin [`SyllableKey`] and its byte
/// span in the original two-key (or one-key incomplete) input, with the tone
/// a third byte carried under `USE_TONE`.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct DoublePinyinKey {
    key: SyllableKey,
    start: usize,
    end: usize,
    tone: u8,
}

impl DoublePinyinKey {
    /// The full-pinyin key this double-pinyin spelling resolves to.
    #[must_use]
    pub const fn key(self) -> SyllableKey {
        self.key
    }

    /// Inclusive byte offset of the first input key.
    #[must_use]
    pub const fn start(self) -> usize {
        self.start
    }

    /// Exclusive byte offset one past the last input key.
    #[must_use]
    pub const fn end(self) -> usize {
        self.end
    }

    /// The tone a third input byte carried under `USE_TONE` (`1`..=`5`);
    /// `0` for the two-key and one-key forms.
    #[must_use]
    pub const fn tone(self) -> u8 {
        self.tone
    }
}

/// Result of one greedy double-pinyin parse.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct DoublePinyinParse {
    keys: Vec<DoublePinyinKey>,
    consumed: usize,
}

impl DoublePinyinParse {
    /// The parsed keys in input order.
    #[must_use]
    pub fn keys(&self) -> &[DoublePinyinKey] {
        &self.keys
    }

    /// Number of original input bytes consumed.
    #[must_use]
    pub const fn consumed(&self) -> usize {
        self.consumed
    }

    /// The parsed keys as a `'`-joined full-pinyin string.
    ///
    /// Used by the compatibility layer to drive the existing decoder
    /// without turning double-pinyin keys back into shorter full-pinyin
    /// segmentations.
    #[must_use]
    pub fn full_pinyin(&self) -> String {
        self.keys
            .iter()
            .map(|item| item.key.text())
            .collect::<Vec<_>>()
            .join("'")
    }
}

/// `FullPinyinScheme` from `src/storage/pinyin_custom2.h:98-104`.
///
/// HANYU (the frozen `crate::parser` surface) stays the default —
/// `FULL_PINYIN_DEFAULT = FULL_PINYIN_HANYU` and the parser constructor
/// calls `set_scheme(FULL_PINYIN_DEFAULT)` (`pinyin_parser2.cpp:158-165,
/// 383-401`). LUOMA and `SECONDARY_ZHUYIN` switch the parser onto their
/// pinned indexes in `crate::full_pinyin_index`; the out-of-enum
/// `abort()` slot is deliberately not modelled here (contract-lock
/// workstream).
#[derive(
    Clone, Copy, Debug, Default, Eq, PartialEq, num_enum::TryFromPrimitive, num_enum::IntoPrimitive,
)]
#[repr(i32)]
pub enum FullPinyinScheme {
    /// Hanyu pinyin (the default).
    #[default]
    Hanyu = 1,
    /// Luoma pinyin.
    Luoma = 2,
    /// Secondary zhuyin romanization.
    SecondaryZhuyin = 3,
}

impl FullPinyinScheme {
    /// The pinned spelling index this scheme parses through, or `None`
    /// for HANYU (the frozen parser surface).
    #[must_use]
    pub const fn index(self) -> Option<crate::FullPinyinIndex> {
        match self {
            Self::Luoma => Some(crate::full_pinyin_index::luoma_pinyin_index()),
            Self::SecondaryZhuyin => Some(crate::full_pinyin_index::secondary_zhuyin_index()),
            Self::Hanyu => None,
        }
    }
}

/// `DoublePinyinScheme` from `src/storage/pinyin_custom2.h:108-117`.
#[derive(
    Clone, Copy, Debug, Default, Eq, PartialEq, num_enum::TryFromPrimitive, num_enum::IntoPrimitive,
)]
#[repr(i32)]
pub enum DoublePinyinScheme {
    /// Ziranma.
    Zrm = 1,
    /// Microsoft.
    #[default]
    Ms = 2,
    /// Ziguang.
    Ziguang = 3,
    /// ABC.
    Abc = 4,
    /// PYJJ.
    Pyjj = 5,
    /// Xiaohe.
    Xhe = 6,
    /// User's keyboard; not a compiled table.
    Customized = 30,
}

/// Shengmu/yunmu tables are indexed by `a..z` then `;` (`charid` 0..26).
const SCHEME_KEY_COUNT: usize = 27;

type ShengmuTable = [Option<&'static str>; SCHEME_KEY_COUNT];
type YunmuTable = [[Option<&'static str>; 2]; SCHEME_KEY_COUNT];
type FallbackTable = &'static [(&'static str, &'static str)];

include!("table_data/double_pinyin.rs");

/// One double-pinyin scheme's three source tables.
#[derive(Clone, Copy)]
struct SchemeTables {
    shengmu: &'static ShengmuTable,
    yunmu: &'static YunmuTable,
    fallback: Option<FallbackTable>,
}

impl DoublePinyinScheme {
    /// The compiled source tables for this scheme, or `None` for
    /// `Customized`.
    const fn tables(self) -> Option<SchemeTables> {
        match self {
            Self::Zrm => Some(SchemeTables {
                shengmu: &ZRM_SHENG,
                yunmu: &ZRM_YUN,
                fallback: Some(ZRM_FALLBACK),
            }),
            Self::Ms => Some(SchemeTables {
                shengmu: &MS_SHENG,
                yunmu: &MS_YUN,
                fallback: None,
            }),
            Self::Ziguang => Some(SchemeTables {
                shengmu: &ZG_SHENG,
                yunmu: &ZG_YUN,
                fallback: None,
            }),
            Self::Abc => Some(SchemeTables {
                shengmu: &ABC_SHENG,
                yunmu: &ABC_YUN,
                fallback: None,
            }),
            Self::Pyjj => Some(SchemeTables {
                shengmu: &PYJJ_SHENG,
                yunmu: &PYJJ_YUN,
                fallback: Some(PYJJ_FALLBACK),
            }),
            Self::Xhe => Some(SchemeTables {
                shengmu: &XHE_SHENG,
                yunmu: &XHE_YUN,
                fallback: Some(XHE_FALLBACK),
            }),
            Self::Customized => None,
        }
    }
}

/// Whether `byte` is a double-pinyin input key.
const fn is_key(byte: u8) -> bool {
    byte.is_ascii_lowercase() || byte == b';'
}

fn key_id(byte: u8) -> usize {
    if byte == b';' {
        SCHEME_KEY_COUNT - 1
    } else {
        usize::from(byte - b'a')
    }
}

/// Looks a spelling up in the frozen full-pinyin inventory, applying the two
/// corrections `DoublePinyinParser2::parse_one_key` forces upstream
/// (`PINYIN_CORRECT_UE_VE` and `PINYIN_CORRECT_V_U`,
/// `src/storage/pinyin_parser2.cpp:434-436`).
fn lookup_pinyin(spelling: &str) -> Option<SyllableKey> {
    if let Some(key) = SyllableKey::from_text(spelling) {
        return Some(key);
    }

    if matches!(spelling, "lue" | "nue") {
        let corrected = format!("{}ve", &spelling[..1]);
        return SyllableKey::from_text(&corrected);
    }

    let first = spelling.as_bytes().first().copied()?;
    if matches!(first, b'j' | b'q' | b'x' | b'y') && spelling.contains('v') {
        let corrected = spelling.replace('v', "u");
        return SyllableKey::from_text(&corrected);
    }

    None
}

/// Stateless parser for one double-pinyin scheme.
///
/// The optional `suppress_fallback` flag reproduces upstream's
/// half-mutation state: `DoublePinyinParser2::set_scheme` clears
/// `m_fallback_table` unconditionally (`pinyin_parser2.cpp:580`) before
/// checking the discriminant, so an out-of-enum call leaves the shengmu
/// and yunmu tables intact but the fallback pointer null. The builder
/// [`Self::with_fallback_suppressed`] creates that state.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct DoublePinyinParser {
    scheme: DoublePinyinScheme,
    /// When `true`, the fallback table for schemes that have one
    /// (ZRM/PYJJ/XHE) is suppressed — the parser behaves as though
    /// upstream cleared `m_fallback_table` without touching the scheme's
    /// shengmu/yunmu tables.
    suppress_fallback: bool,
}

impl DoublePinyinParser {
    /// A parser for the scheme's default (`DOUBLE_PINYIN_MS`).
    #[must_use]
    pub const fn new() -> Self {
        Self {
            scheme: DoublePinyinScheme::Ms,
            suppress_fallback: false,
        }
    }

    /// A parser for a specific scheme.
    #[must_use]
    pub const fn with_scheme(scheme: DoublePinyinScheme) -> Self {
        Self {
            scheme,
            suppress_fallback: false,
        }
    }

    /// Returns a copy of this parser with the fallback table suppressed,
    /// reproducing the state upstream enters when `set_scheme` clears
    /// `m_fallback_table` without assigning a new scheme
    /// (`pinyin_parser2.cpp:580`).
    #[must_use]
    pub const fn with_fallback_suppressed(mut self) -> Self {
        self.suppress_fallback = true;
        self
    }

    /// Selects a scheme. Returns `false` and keeps the current scheme for
    /// `Customized`, mirroring upstream's lack of a compiled table there
    /// (`src/storage/pinyin_parser2.cpp:610-612`) without the abort.
    /// A successful switch clears the suppressed-fallback flag.
    pub fn set_scheme(&mut self, scheme: DoublePinyinScheme) -> bool {
        if scheme == DoublePinyinScheme::Customized {
            return false;
        }
        self.scheme = scheme;
        self.suppress_fallback = false;
        true
    }

    /// The scheme in force.
    #[must_use]
    pub const fn scheme(self) -> DoublePinyinScheme {
        self.scheme
    }

    /// Greedily parses `input`, mirroring `DoublePinyinParser2::parse`
    /// (`src/storage/pinyin_parser2.cpp:531-574`), driven by the caller's
    /// **full option word** (`pinyin_parse_more_double_pinyins`,
    /// `src/pinyin.cpp:1543`):
    /// the `USE_TONE`, `FORCE_TONE`, and `PINYIN_INCOMPLETE` bits are read
    /// off the word exactly as upstream's `DoublePinyinParser2::parse`
    /// reads its caller options. `FORCE_TONE` requires a three-byte key
    /// (`pinyin_parser2.cpp:412`); a three-byte key carries its trailing
    /// `1`..=`5` digit as the tone only under `USE_TONE` (`:439-451`), so
    /// `FORCE_TONE` without `USE_TONE` consumes nothing at all. The
    /// one-byte incomplete probe runs under `PINYIN_INCOMPLETE`
    /// (`:418-421`). Correction and ambiguity bits never cross: the
    /// two-key lookup is `lookup_pinyin`'s forced-`UE_VE`/`V_U` law
    /// whatever the word carries (`:409, :434-436`).
    #[must_use]
    pub fn parse_with_options(&self, input: &[u8], options: OptionBits) -> DoublePinyinParse {
        let Some(mut tables) = self.scheme.tables() else {
            return DoublePinyinParse::default();
        };
        if self.suppress_fallback {
            tables.fallback = None;
        }
        let use_tone = options.contains(OptionBits::USE_TONE);
        let force_tone = options.contains(OptionBits::FORCE_TONE);
        let allow_incomplete = options.contains(OptionBits::PINYIN_INCOMPLETE);

        // The probe window is option-blind, exactly upstream: tone digits
        // extend it even without USE_TONE (`:538-545`).
        let maximum_len = input
            .iter()
            .take_while(|&&byte| is_key(byte) || (b'1'..=b'5').contains(&byte))
            .count();

        let mut keys = Vec::new();
        let mut parsed_len = 0;
        while parsed_len < maximum_len {
            let remaining = &input[parsed_len..maximum_len];
            let try_len = remaining.len().min(3);
            let mut matched = None;
            for len in (1..=try_len).rev() {
                if let Some((key, tone)) = probe_one_key(
                    &input[parsed_len..parsed_len + len],
                    use_tone,
                    force_tone,
                    allow_incomplete,
                    tables,
                ) {
                    matched = Some((key, tone, len));
                    break;
                }
            }

            let Some((key, tone, len)) = matched else {
                break;
            };
            keys.push(DoublePinyinKey {
                key,
                start: parsed_len,
                end: parsed_len + len,
                tone,
            });
            parsed_len += len;
        }

        DoublePinyinParse {
            keys,
            consumed: parsed_len,
        }
    }

    /// Parses one double-pinyin key from the whole of `input`, mirroring
    /// `DoublePinyinParser2::parse_one_key`
    /// (`src/storage/pinyin_parser2.cpp:405-530`).
    ///
    /// `options` is the caller's option word, with the law the batch
    /// [`Self::parse_with_options`] does not carry: correction and ambiguity bits are
    /// masked first (`:409`); `FORCE_TONE` requires a three-byte input
    /// (`:412`); the one-byte incomplete probe runs under
    /// `PINYIN_INCOMPLETE` (`:418-421`); and the two/three-byte probe
    /// masks the incomplete bits and forces the `UE_VE`/`V_U`
    /// corrections (`:433-436` — already `lookup_pinyin`'s law), with
    /// a three-byte input's trailing `1..=5` riding the key as the tone
    /// under `USE_TONE` (`:439-451`). A two-byte match carries tone
    /// zero. `None` is the upstream `false`.
    #[must_use]
    pub fn parse_one_key(&self, options: OptionBits, input: &[u8]) -> Option<ChewingKey> {
        let options = options - (OptionBits::PINYIN_CORRECT_ALL | OptionBits::PINYIN_AMB_ALL);
        if options.contains(OptionBits::FORCE_TONE) && input.len() != 3 {
            return None;
        }
        let mut tables = self.scheme.tables()?;
        if self.suppress_fallback {
            tables.fallback = None;
        }
        match input.len() {
            1 => {
                let syllable = parse_incomplete(
                    input[0],
                    options.contains(OptionBits::PINYIN_INCOMPLETE),
                    tables,
                )?;
                ChewingKey::from_pinyin(syllable.text())
            }
            2 | 3 => {
                let mut tone = 0;
                if input.len() == 3 {
                    if !options.contains(OptionBits::USE_TONE) {
                        return None;
                    }
                    tone = match input[2] {
                        byte @ b'1'..=b'5' => byte - b'0',
                        _ => return None,
                    };
                }
                let syllable = parse_two_keys(&input[..2], tables)?;
                Some(ChewingKey::from_pinyin(syllable.text())?.with_tone(tone))
            }
            _ => None,
        }
    }
}

impl Default for DoublePinyinParser {
    fn default() -> Self {
        Self::new()
    }
}

/// One greedy-walk probe of `DoublePinyinParser2::parse_one_key`
/// (`src/storage/pinyin_parser2.cpp:405-530`) under the batch law's three
/// caller bits: the `FORCE_TONE` length-3 gate (`:412`), the one-byte
/// incomplete probe under `PINYIN_INCOMPLETE` (`:415-432`), and the
/// three-byte tone parse under `USE_TONE` (`:439-451`). The answer is the
/// resolved key plus the tone the third byte carried (`0` for the
/// one/two-byte forms). Without `USE_TONE` a three-byte slice refuses and
/// the walk retries length 2 — the tone-less profile.
fn probe_one_key(
    input: &[u8],
    use_tone: bool,
    force_tone: bool,
    allow_incomplete: bool,
    tables: SchemeTables,
) -> Option<(SyllableKey, u8)> {
    if force_tone && input.len() != 3 {
        return None;
    }
    match input.len() {
        1 => parse_incomplete(input[0], allow_incomplete, tables).map(|key| (key, 0)),
        2 => parse_two_keys(input, tables).map(|key| (key, 0)),
        3 => {
            if !use_tone {
                return None;
            }
            let tone = match input[2] {
                byte @ b'1'..=b'5' => byte - b'0',
                _ => return None,
            };
            parse_two_keys(&input[..2], tables).map(|key| (key, tone))
        }
        _ => None,
    }
}

fn parse_incomplete(byte: u8, allow_incomplete: bool, tables: SchemeTables) -> Option<SyllableKey> {
    if !allow_incomplete || !is_key(byte) {
        return None;
    }
    let sheng = tables.shengmu[key_id(byte)]?;
    if sheng == "'" {
        return None;
    }
    SyllableKey::from_text(sheng)
}

fn parse_two_keys(input: &[u8], tables: SchemeTables) -> Option<SyllableKey> {
    if !is_key(input[0]) || !is_key(input[1]) {
        return None;
    }

    let sheng = match tables.shengmu[key_id(input[0])] {
        None => return parse_fallback(input, tables),
        Some("'") => "",
        Some(value) => value,
    };
    let yun = &tables.yunmu[key_id(input[1])];

    if yun[0].is_none() {
        return parse_fallback(input, tables);
    }

    for candidate in yun.iter().flatten() {
        let spelling = format!("{sheng}{candidate}");
        if let Some(key) = lookup_pinyin(&spelling) {
            return Some(key);
        }
    }

    parse_fallback(input, tables)
}

fn parse_fallback(input: &[u8], tables: SchemeTables) -> Option<SyllableKey> {
    let table = tables.fallback?;
    let text = core::str::from_utf8(input).ok()?;
    table
        .iter()
        .find_map(|(keys, yunmu)| (*keys == text).then_some(*yunmu))
        .and_then(lookup_pinyin)
}

/// `ZhuyinScheme` from `src/storage/pinyin_custom2.h:122-133`.
///
/// Eight of the nine keyboards parse ([`ZhuyinParser`]: Standard, Hsu,
/// Ibm, Ginyieh, Eten, Eten26, `HsuDvorak`, `DachenCp26`); `StandardDvorak`
/// is the one gap — upstream's setter aborts on it
/// (`zhuyin_parser2.cpp:291-295`, recorded in
/// `docs/findings/compatibility-policy.md`, row 5c). The C API setters abort
/// there as the pin does; `ZhuyinParser::set_scheme` returns `false` and
/// keeps the current scheme.
#[derive(
    Clone, Copy, Debug, Default, Eq, PartialEq, num_enum::TryFromPrimitive, num_enum::IntoPrimitive,
)]
#[repr(i32)]
pub enum ZhuyinScheme {
    /// Standard keyboard.
    #[default]
    Standard = 1,
    /// Hsu keyboard.
    Hsu = 2,
    /// IBM keyboard.
    Ibm = 3,
    /// Gin-Yieh keyboard.
    Ginyieh = 4,
    /// Eten keyboard.
    Eten = 5,
    /// Eten 26 keyboard.
    Eten26 = 6,
    /// Standard Dvorak keyboard.
    StandardDvorak = 7,
    /// Hsu Dvorak keyboard.
    HsuDvorak = 8,
    /// Dachen CP26 keyboard.
    DachenCp26 = 9,
}

/// Stores the original keystroke span, the tone-less full-pinyin
/// [`SyllableKey`] ID, and the parsed tone.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ZhuyinKey {
    key: SyllableKey,
    start: usize,
    end: usize,
    tone: u8,
}

impl ZhuyinKey {
    /// The full-pinyin key this Zhuyin spelling resolves to.
    #[must_use]
    pub const fn key(&self) -> SyllableKey {
        self.key
    }

    /// Inclusive byte offset of the first keystroke.
    #[must_use]
    pub const fn start(&self) -> usize {
        self.start
    }

    /// Exclusive byte offset one past the last keystroke.
    #[must_use]
    pub const fn end(&self) -> usize {
        self.end
    }

    /// Tone number (1..5), or 0 for zero tone.
    #[must_use]
    pub const fn tone(&self) -> u8 {
        self.tone
    }

    /// The key's canonical Zhuyin spelling plus the tone mark, matching
    /// `_ChewingKey::get_zhuyin_string` (`src/storage/chewing_key.cpp:74-89`):
    /// first and zero tones render the bare spelling; tones 2..5 append their
    /// tone mark. A shuffled input renders canonically, because the matched
    /// row's key is its `content_table` entry.
    #[must_use]
    pub fn display(&self) -> String {
        self.key
            .chewing_key()
            .with_tone(self.tone)
            .zhuyin_text()
            .to_string()
    }
}

/// Result of one greedy Zhuyin parse.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct ZhuyinParse {
    keys: Vec<ZhuyinKey>,
    consumed: usize,
}

impl ZhuyinParse {
    /// The parsed keys in input order.
    #[must_use]
    pub fn keys(&self) -> &[ZhuyinKey] {
        &self.keys
    }

    /// Number of original input bytes consumed.
    #[must_use]
    pub const fn consumed(&self) -> usize {
        self.consumed
    }

    /// The parsed keys as a `'`-joined tone-less full-pinyin string.
    #[must_use]
    #[cfg(test)]
    fn full_pinyin(&self) -> String {
        self.keys
            .iter()
            .map(|item| item.key.text())
            .collect::<Vec<_>>()
            .join("'")
    }
}

/// One Simple keyboard's source tables: key-to-symbol and key-to-tone
/// rows ported verbatim from the pinned `zhuyin_table.h`. Linear scan by
/// key, exactly like upstream's `search_chewing_symbols` /
/// `search_chewing_tones` ("we only have < 50 items").
#[derive(Clone, Copy)]
struct SimpleTables {
    /// `(key, zhuyin symbol)` rows.
    symbols: &'static [(u8, &'static str)],
    /// `(key, tone number)` rows.
    tones: &'static [(u8, u8)],
    /// The global chewing index every Simple keyboard shares.
    index: crate::zhuyin_map::ZhuyinIndex,
}

impl SimpleTables {
    /// The symbol string one key maps to, if it is a symbol key.
    fn symbol(&self, byte: u8) -> Option<&'static str> {
        self.symbols
            .iter()
            .find(|(key, _)| *key == byte)
            .map(|(_, symbol)| *symbol)
    }

    /// The tone one key spells, if it is a tone key.
    fn tone(&self, byte: u8) -> Option<u8> {
        self.tones
            .iter()
            .find(|(key, _)| *key == byte)
            .map(|(_, tone)| *tone)
    }
}

/// One Discrete keyboard's source tables: separate initial/middle/final
/// symbol tables plus tones and the keyboard's own index, ported verbatim
/// from the pinned `zhuyin_table.h` / `pinyin_parser_table.h`.
///
/// A key may appear twice in one table (the dual-mapped keys: Hsu `c` →
/// ㄒ/ㄕ). Parsing resolves the **first** matching row — upstream's
/// `search_chewing_symbols` returns on first hit — while the display
/// surface collects every row, upstream's `search_chewing_symbols2`.
#[derive(Clone, Copy)]
struct DiscreteTables {
    /// `(key, zhuyin symbol)` initial-slot rows, pinned order.
    initials: &'static [(u8, &'static str)],
    /// Middle-slot rows.
    middles: &'static [(u8, &'static str)],
    /// Final-slot rows.
    finals: &'static [(u8, &'static str)],
    /// `(key, tone number)` rows.
    tones: &'static [(u8, u8)],
    /// The keyboard's own chewing index.
    index: crate::zhuyin_map::ZhuyinIndex,
    /// The correction bit `ZhuyinDiscreteParser2::set_scheme` forces for
    /// this keyboard (`zhuyin_parser2.cpp:474-490`).
    correction: OptionBits,
}

impl DiscreteTables {
    /// The first-matching symbol for `byte` in `table`, matching
    /// upstream's `search_chewing_symbols`.
    fn first_symbol(table: &'static [(u8, &'static str)], byte: u8) -> Option<&'static str> {
        table
            .iter()
            .find(|(key, _)| *key == byte)
            .map(|(_, symbol)| *symbol)
    }

    /// Every symbol `byte` maps to in `table`, matching upstream's
    /// `search_chewing_symbols2` (at most two rows per key).
    fn all_symbols(table: &'static [(u8, &'static str)], byte: u8) -> Vec<&'static str> {
        table
            .iter()
            .filter(|(key, _)| *key == byte)
            .map(|(_, symbol)| *symbol)
            .collect()
    }

    /// The tone one key spells, if it is a tone key.
    fn tone(&self, byte: u8) -> Option<u8> {
        self.tones
            .iter()
            .find(|(key, _)| *key == byte)
            .map(|(_, tone)| *tone)
    }
}

/// The `DaChen` CP26 keyboard's source tables: initial/middle/final symbol
/// tables plus tones, ported verbatim from the pinned `zhuyin_table.h`.
/// The parser is constructor-configured over these and the **global**
/// index (`ZhuyinDaChenCP26Parser2` has no `set_scheme` and no
/// `m_options`, `zhuyin_parser2.cpp:541-558`), so no correction bit
/// applies — the repeat-count probe always builds spellings in canonical
/// initial+middle+final order, which the plain rows already cover.
#[derive(Clone, Copy)]
struct Cp26Tables {
    /// `(key, zhuyin symbol)` initial-slot rows, pinned order.
    initials: &'static [(u8, &'static str)],
    /// Middle-slot rows.
    middles: &'static [(u8, &'static str)],
    /// Final-slot rows.
    finals: &'static [(u8, &'static str)],
    /// `(key, tone number)` rows.
    tones: &'static [(u8, u8)],
}

impl Cp26Tables {
    /// The tone one key spells, if it is a tone key.
    fn tone(&self, byte: u8) -> Option<u8> {
        self.tones
            .iter()
            .find(|(key, _)| *key == byte)
            .map(|(_, tone)| *tone)
    }
}

include!("table_data/zhuyin_keyboards.rs");

include!("table_data/tone_symbols.rs");

/// `search_chewing_index` + `check_chewing_options`
/// (`src/storage/zhuyin_parser2.cpp:43-100`): binary search the sorted
/// zhuyin index (at most one hit), gate the row's flags against the
/// parser's option word, and return the row's key — its `content_table`
/// entry, whose zhuyin upstream renders through `ChewingKey::
/// get_zhuyin_string`, so a shuffled input displays canonically. The
/// search compares the whole spelling, so no second equality test
/// follows it.
///
/// `options` carries only parser-owned bits — `ZHUYIN_CORRECT_SHUFFLE`
/// (forced by `ZhuyinSimpleParser2::set_scheme`, `:272`) and optionally
/// `ZHUYIN_INCOMPLETE` passed through from the caller's option word
/// (`pinyin.cpp` strips `ZHUYIN_CORRECT_ALL` from caller options at every
/// chewing entry point, so caller corrections can never reach this gate).
fn search_zhuyin_index(
    index: crate::zhuyin_map::ZhuyinIndex,
    zhuyin: &str,
    options: OptionBits,
) -> Option<SyllableKey> {
    let (key, flags) = index.get(index.position(zhuyin)?)?;
    // An incomplete row needs its option bit; a correction-flagged row
    // needs every correction bit present ((flags & options) != flags
    // rejects).
    if flags.contains(OptionBits::ZHUYIN_INCOMPLETE)
        && !options.contains(OptionBits::ZHUYIN_INCOMPLETE)
    {
        return None;
    }
    if !options.contains(flags & (OptionBits::ZHUYIN_CORRECT_ALL | OptionBits::PINYIN_AMB_ALL)) {
        return None;
    }
    Some(key)
}

/// `ZhuyinDirectParser2::parse` (`zhuyin_parser2.cpp:914-958`): the input
/// splits at every `' '` and `'\''`, each segment must be one whole key
/// (`parse_zhuyin_direct_key`), and the parse stops at the first segment
/// that is not — the keys before it are the result. Returns the keys as
/// `(syllable, tone)`.
#[must_use]
pub fn parse_zhuyin_direct(input: &str, options: OptionBits) -> Vec<(SyllableKey, u8)> {
    let mut keys = Vec::new();
    crate::direct::parse(
        input.as_bytes(),
        |span| {
            input
                .get(span)
                .and_then(|segment| parse_zhuyin_direct_key(segment, options))
        },
        |key, _| keys.push(key),
    );
    keys
}

/// `ZhuyinDirectParser2::parse_one_key` (`zhuyin_parser2.cpp:858-912`):
/// the tone defaults to 1; under `USE_TONE` a trailing tone symbol
/// (`chewing_tone_table[1..]`) sets it and is cut off; the rest must be a
/// `zhuyin_index` spelling admitted by `check_chewing_options` with the
/// ambiguity bits cleared. `FORCE_TONE` never refuses: the default tone
/// is already non-zero.
pub(crate) fn parse_zhuyin_direct_key(
    segment: &str,
    options: OptionBits,
) -> Option<(SyllableKey, u8)> {
    let options = options - OptionBits::PINYIN_AMB_ALL;
    let last = segment.chars().last()?;
    let mut tone = 1_u8;
    let mut body = segment;
    if options.contains(OptionBits::USE_TONE) {
        let mut buffer = [0_u8; 4];
        let last = last.encode_utf8(&mut buffer);
        if let Some(found) = (1..=5).find(|&t| tone_symbol(t) == last) {
            tone = found;
            body = &segment[..segment.len() - last.len()];
        }
    }
    if body.is_empty() {
        return None;
    }
    let key = search_zhuyin_index(crate::zhuyin_map::zhuyin_pinyin_map(), body, options)?;
    Some((key, tone))
}

/// The compiled keyboard behind a scheme: a Simple symbol/tone pair over
/// the global index, a Discrete initial/middle/final set over the
/// keyboard's own index, or the CP26 repeat-count keyboard over the
/// global index.
#[derive(Clone, Copy)]
enum Keyboard {
    /// STANDARD, IBM, GINYIEH, ETEN.
    Simple(SimpleTables),
    /// HSU, ETEN26, `HSU_DVORAK`.
    Discrete(DiscreteTables),
    /// `DACHEN_CP26`.
    Cp26(Cp26Tables),
}

/// Stateless parser for one Zhuyin keyboard.
///
/// The Simple keyboards (STANDARD, IBM, GINYIEH, ETEN) are implemented
/// table-driven over the shared `crate::zhuyin_map` index; the
/// Discrete keyboards (HSU, ETEN26, `HSU_DVORAK`) probe initial/middle/
/// final/tone positions against their own tables and indexes; CP26 and
/// the `STANDARD_DVORAK` abort slot parse nothing and their setters
/// report `false`.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ZhuyinParser {
    scheme: ZhuyinScheme,
}

impl ZhuyinScheme {
    /// The compiled Simple tables for this scheme, or `None` for the
    /// non-Simple keyboards.
    fn simple_tables(self) -> Option<SimpleTables> {
        match self {
            Self::Standard => Some(SimpleTables {
                symbols: STANDARD_SYMBOLS,
                tones: STANDARD_TONES,
                index: crate::zhuyin_map::zhuyin_pinyin_map(),
            }),
            Self::Ibm => Some(SimpleTables {
                symbols: IBM_SYMBOLS,
                tones: IBM_TONES,
                index: crate::zhuyin_map::zhuyin_pinyin_map(),
            }),
            Self::Ginyieh => Some(SimpleTables {
                symbols: GINYIEH_SYMBOLS,
                tones: GINYIEH_TONES,
                index: crate::zhuyin_map::zhuyin_pinyin_map(),
            }),
            Self::Eten => Some(SimpleTables {
                symbols: ETEN_SYMBOLS,
                tones: ETEN_TONES,
                index: crate::zhuyin_map::zhuyin_pinyin_map(),
            }),
            Self::Hsu
            | Self::Eten26
            | Self::StandardDvorak
            | Self::HsuDvorak
            | Self::DachenCp26 => None,
        }
    }

    /// The compiled Discrete tables for this scheme, or `None` for the
    /// non-Discrete keyboards. Mirrors
    /// `ZhuyinDiscreteParser2::set_scheme` (`zhuyin_parser2.cpp:474-490`):
    /// HSU forces `ZHUYIN_CORRECT_HSU` over `hsu_zhuyin_index`, ETEN26
    /// forces `ZHUYIN_CORRECT_ETEN26` over `eten26_zhuyin_index`, and
    /// `HSU_DVORAK` forces the HSU bit over the shared `hsu_zhuyin_index`
    /// with its own (at this pin byte-identical) key tables.
    fn discrete_tables(self) -> Option<DiscreteTables> {
        match self {
            Self::Hsu => Some(DiscreteTables {
                initials: HSU_INITIALS,
                middles: HSU_MIDDLES,
                finals: HSU_FINALS,
                tones: HSU_TONES,
                index: crate::zhuyin_map::hsu_zhuyin_index(),
                correction: OptionBits::ZHUYIN_CORRECT_HSU,
            }),
            Self::Eten26 => Some(DiscreteTables {
                initials: ETEN26_INITIALS,
                middles: ETEN26_MIDDLES,
                finals: ETEN26_FINALS,
                tones: ETEN26_TONES,
                index: crate::zhuyin_map::eten26_zhuyin_index(),
                correction: OptionBits::ZHUYIN_CORRECT_ETEN26,
            }),
            Self::HsuDvorak => Some(DiscreteTables {
                initials: HSU_DVORAK_INITIALS,
                middles: HSU_DVORAK_MIDDLES,
                finals: HSU_DVORAK_FINALS,
                tones: HSU_DVORAK_TONES,
                index: crate::zhuyin_map::hsu_zhuyin_index(),
                correction: OptionBits::ZHUYIN_CORRECT_HSU,
            }),
            Self::Standard
            | Self::Ibm
            | Self::Ginyieh
            | Self::Eten
            | Self::StandardDvorak
            | Self::DachenCp26 => None,
        }
    }

    /// The CP26 tables, `None` for every other scheme.
    const fn cp26_tables(self) -> Option<Cp26Tables> {
        match self {
            Self::DachenCp26 => Some(Cp26Tables {
                initials: CP26_INITIALS,
                middles: CP26_MIDDLES,
                finals: CP26_FINALS,
                tones: CP26_TONES,
            }),
            Self::Standard
            | Self::Hsu
            | Self::Ibm
            | Self::Ginyieh
            | Self::Eten
            | Self::Eten26
            | Self::StandardDvorak
            | Self::HsuDvorak => None,
        }
    }

    /// The compiled keyboard for this scheme, `None` for the dvorak
    /// abort slot.
    fn keyboard(self) -> Option<Keyboard> {
        if let Some(tables) = self.simple_tables() {
            return Some(Keyboard::Simple(tables));
        }
        if let Some(tables) = self.discrete_tables() {
            return Some(Keyboard::Discrete(tables));
        }
        self.cp26_tables().map(Keyboard::Cp26)
    }
}

impl ZhuyinParser {
    /// A parser for `ZHUYIN_DEFAULT = ZHUYIN_STANDARD`.
    #[must_use]
    pub const fn new() -> Self {
        Self {
            scheme: ZhuyinScheme::Standard,
        }
    }

    /// A parser for a specific scheme.
    #[must_use]
    pub const fn with_scheme(scheme: ZhuyinScheme) -> Self {
        Self { scheme }
    }

    /// Selects a scheme. The Simple keyboards (STANDARD, IBM, GINYIEH,
    /// ETEN) switch tables the way upstream's `set_scheme` does
    /// (`src/storage/zhuyin_parser2.cpp:271-300`) and the Discrete
    /// keyboards (HSU, ETEN26, `HSU_DVORAK`) the way theirs does
    /// (`:474-490`) — both minus upstream's aborts; everything else
    /// reports `false` and keeps the current scheme.
    #[cfg(test)]
    fn set_scheme(&mut self, scheme: ZhuyinScheme) -> bool {
        if scheme.keyboard().is_none() {
            return false;
        }
        self.scheme = scheme;
        true
    }

    /// The scheme in force.
    #[must_use]
    pub const fn scheme(self) -> ZhuyinScheme {
        self.scheme
    }

    /// Whether `key` is part of the current keyboard.
    #[must_use]
    pub fn in_scheme(&self, key: u8, use_tone: bool) -> bool {
        !self.symbols_for(key, use_tone).is_empty()
    }

    /// The Zhuyin symbol(s) mapped by one keystroke.
    ///
    /// Simple keyboards return at most one symbol; a Discrete key can
    /// hit the initial, middle, and final tables at once (dual-mapped
    /// keys contribute both rows), so up to three symbols plus the tone
    /// mark come back — exactly `ZhuyinDiscreteParser2::
    /// in_chewing_scheme`'s vector (`zhuyin_parser2.cpp:496-545`).
    #[must_use]
    pub fn symbols_for(&self, key: u8, use_tone: bool) -> Vec<String> {
        match self.scheme.keyboard() {
            Some(Keyboard::Simple(tables)) => {
                let mut symbols = Vec::new();
                if let Some(symbol) = tables.symbol(key) {
                    symbols.push(symbol.to_owned());
                }
                if use_tone && let Some(tone) = tables.tone(key) {
                    symbols.push(tone_symbol(tone).to_owned());
                }
                symbols
            }
            Some(Keyboard::Discrete(tables)) => {
                let mut symbols = Vec::new();
                for table in [tables.initials, tables.middles, tables.finals] {
                    symbols.extend(
                        DiscreteTables::all_symbols(table, key)
                            .into_iter()
                            .map(str::to_owned),
                    );
                }
                if use_tone && let Some(tone) = tables.tone(key) {
                    symbols.push(tone_symbol(tone).to_owned());
                }
                symbols
            }
            Some(Keyboard::Cp26(tables)) => {
                // ZhuyinDaChenCP26Parser2::in_chewing_scheme
                // (`zhuyin_parser2.cpp:796-844`): initial, middle, and
                // final hits (both rows of a dual key), the display-only
                // "ㄧㄚ" extra for 'i', then the tone mark.
                let mut symbols = Vec::new();
                for table in [tables.initials, tables.middles, tables.finals] {
                    symbols.extend(
                        DiscreteTables::all_symbols(table, key)
                            .into_iter()
                            .map(str::to_owned),
                    );
                }
                if key == b'i' {
                    symbols.push("ㄧㄚ".to_owned());
                }
                if use_tone && let Some(tone) = tables.tone(key) {
                    symbols.push(tone_symbol(tone).to_owned());
                }
                symbols
            }
            None => Vec::new(),
        }
    }

    /// Greedily parses `input`, mirroring `ZhuyinSimpleParser2::parse`
    /// (`src/storage/zhuyin_parser2.cpp:216-268`) and
    /// `ZhuyinDiscreteParser2::parse` (`:408-460`) — the same greedy
    /// shell — including the post-match `is_valid_zhuyin` abort
    /// (`:256-257`, `_ChewingKey::is_valid_zhuyin` at
    /// `chewing_key.cpp:38-45`).
    ///
    /// The caller's **full option word** (`zhuyin_parse_more_chewings`,
    /// `zhuyin.cpp:1058-1082`) supplies the `USE_TONE`, `FORCE_TONE` and
    /// `ZHUYIN_INCOMPLETE` bits, read exactly as upstream's
    /// `ZhuyinSimpleParser2` / Discrete / CP26 batch parsers read their
    /// caller options (`options |= m_options`, `zhuyin_parser2.cpp:221,413`).
    /// The parser additionally owns its keyboard's correction bit, which
    /// upstream's `set_scheme` forces (SHUFFLE for Simple, `:272`; HSU /
    /// ETEN26 for Discrete, `:474-490`) and `parse` or's into the option
    /// word (`:221`, `:413`); `FORCE_TONE` is honoured per keyboard family.
    ///
    /// Both C facades' `*_parse_more_chewings` seams drive this method with
    /// their own forwarding law — the pinyin facade's word minus
    /// `ZHUYIN_CORRECT_ALL`, the zhuyin facade's whole word (its pin
    /// default carries `USE_TONE | FORCE_TONE`).
    #[must_use]
    pub fn parse_with_options(&self, input: &[u8], options: OptionBits) -> ZhuyinParse {
        let use_tone = options.contains(OptionBits::USE_TONE);
        let force_tone = options.contains(OptionBits::FORCE_TONE);
        let allow_incomplete = options.contains(OptionBits::ZHUYIN_INCOMPLETE);
        self.parse_detailed(input, use_tone, force_tone, allow_incomplete)
    }

    fn parse_detailed(
        &self,
        input: &[u8],
        use_tone: bool,
        force_tone: bool,
        allow_incomplete: bool,
    ) -> ZhuyinParse {
        let Some(keyboard) = self.scheme.keyboard() else {
            return ZhuyinParse::default();
        };

        let (maximum_len, probe) =
            self.batch_probe(keyboard, input, use_tone, force_tone, allow_incomplete);

        // max_chewing_dachen26_length = 12 for CP26,
        // max_chewing_length = 4 for every other keyboard.
        let max_key_len = if matches!(keyboard, Keyboard::Cp26(_)) {
            12
        } else {
            4
        };

        let mut keys = Vec::new();
        let mut parsed_len = 0;
        while parsed_len < maximum_len {
            let remaining = &input[parsed_len..maximum_len];
            let try_len = remaining.len().min(max_key_len);
            let Some((key, tone, len)) = probe.longest_key(remaining, try_len) else {
                break;
            };
            // Same stop as upstream `:256-257`: do not retry a shorter key.
            if !is_valid_zhuyin(key, tone) {
                break;
            }
            keys.push(ZhuyinKey {
                key,
                start: parsed_len,
                end: parsed_len + len,
                tone,
            });
            parsed_len += len;
        }

        ZhuyinParse {
            keys,
            consumed: parsed_len,
        }
    }

    /// The batch parse's probe for `keyboard`, and the length of the prefix
    /// of `input` whose bytes are in the keyboard's scheme. The probe takes
    /// the batch path's own option word: the keyboard's correction bits,
    /// plus `ZHUYIN_INCOMPLETE` when `allow_incomplete`.
    fn batch_probe(
        &self,
        keyboard: Keyboard,
        input: &[u8],
        use_tone: bool,
        force_tone: bool,
        allow_incomplete: bool,
    ) -> (usize, KeyProbe) {
        match keyboard {
            Keyboard::Simple(tables) => {
                let options = if allow_incomplete {
                    OptionBits::ZHUYIN_CORRECT_SHUFFLE | OptionBits::ZHUYIN_INCOMPLETE
                } else {
                    OptionBits::ZHUYIN_CORRECT_SHUFFLE
                };
                let maximum_len = input
                    .iter()
                    .take_while(|&&byte| {
                        tables.symbol(byte).is_some() || (use_tone && tables.tone(byte).is_some())
                    })
                    .count();
                (
                    maximum_len,
                    KeyProbe::Simple {
                        tables,
                        use_tone,
                        options,
                        force_tone,
                    },
                )
            }
            Keyboard::Discrete(tables) => {
                let options = if allow_incomplete {
                    tables.correction | OptionBits::ZHUYIN_INCOMPLETE
                } else {
                    tables.correction
                };
                let maximum_len = input
                    .iter()
                    .take_while(|&&byte| {
                        [tables.initials, tables.middles, tables.finals]
                            .iter()
                            .any(|table| table.iter().any(|(key, _)| *key == byte))
                            || (use_tone && tables.tone(byte).is_some())
                    })
                    .count();
                (
                    maximum_len,
                    KeyProbe::Discrete {
                        tables,
                        use_tone,
                        options,
                        force_tone,
                    },
                )
            }
            Keyboard::Cp26(tables) => {
                // CP26 owns no correction bit; only the caller's
                // ZHUYIN_INCOMPLETE crosses into the global index's
                // gate.
                let options = if allow_incomplete {
                    OptionBits::ZHUYIN_INCOMPLETE
                } else {
                    OptionBits::empty()
                };
                let maximum_len = input
                    .iter()
                    .take_while(|&&byte| self.in_scheme(byte, use_tone))
                    .count();
                (
                    maximum_len,
                    KeyProbe::Cp26 {
                        tables,
                        use_tone,
                        options,
                        force_tone,
                    },
                )
            }
        }
    }

    /// Parses one chewing key from the whole of `input`, mirroring the
    /// three upstream `parse_one_key` laws — `ZhuyinSimpleParser2`
    /// (`src/storage/zhuyin_parser2.cpp:162-210`) for the Simple
    /// keyboards, `ZhuyinDiscreteParser2` (`:335-405`) for the Discrete
    /// keyboards, and `ZhuyinDaChenCP26Parser2` (`:573-716`) for CP26 —
    /// through this scheme's `Keyboard` probe.
    ///
    /// `options` is the caller's option word with the ABI layer's
    /// `ZHUYIN_CORRECT_ALL` strip already applied (`pinyin.cpp:1621`).
    /// Unlike the batch [`Self::parse_with_options`], no keyboard-owned correction
    /// bit is forced here and the ambiguity bits are masked (the
    /// `options &= ~PINYIN_AMB_ALL` at `:165`, `:340`, `:580`).
    /// `FORCE_TONE` rejects a toneless match — nested under `USE_TONE`
    /// for Simple and CP26 (`:178`, `:602`), unconditional for Discrete
    /// (`:373`, `:387`). `None` is the upstream `false`, including the
    /// out-of-keyboard and assert shapes; the C adapters abort on the
    /// ones where the pin asserts.
    #[must_use]
    pub fn parse_one_key(&self, options: OptionBits, input: &[u8]) -> Option<ChewingKey> {
        zhuyin_parse_one_key(self.scheme, options, input)
    }
}

/// One greedy step of [`ZhuyinParser::parse_with_options`], specialised per keyboard
/// family: Simple concatenates per-key symbols, Discrete probes the
/// initial/middle/final/tone positions.
#[derive(Clone, Copy)]
enum KeyProbe {
    /// The Simple per-byte concatenation path.
    Simple {
        /// The keyboard's symbol/tone tables.
        tables: SimpleTables,
        /// The `USE_TONE` option.
        use_tone: bool,
        /// The parser-owned option word.
        options: OptionBits,
        /// The `FORCE_TONE` option: a toneless match is rejected, nested
        /// under `USE_TONE` (upstream `zhuyin_parser2.cpp:178`).
        force_tone: bool,
    },
    /// The Discrete positional-probe path.
    Discrete {
        /// The keyboard's slot tables and index.
        tables: DiscreteTables,
        /// The `USE_TONE` option.
        use_tone: bool,
        /// The parser-owned option word.
        options: OptionBits,
        /// The `FORCE_TONE` option: a toneless match is rejected
        /// unconditionally (upstream `zhuyin_parser2.cpp:373,387`).
        force_tone: bool,
    },
    /// The CP26 repeat-count path.
    Cp26 {
        /// The keyboard's slot tables.
        tables: Cp26Tables,
        /// The `USE_TONE` option.
        use_tone: bool,
        /// The parser-owned option word.
        options: OptionBits,
        /// The `FORCE_TONE` option: a toneless match is rejected, nested
        /// under `USE_TONE` (upstream `zhuyin_parser2.cpp:602`).
        force_tone: bool,
    },
}

impl KeyProbe {
    /// The longest key at the start of `input`, tried from `max_len` bytes
    /// down to one: the key, its tone and its length.
    fn longest_key(&self, input: &[u8], max_len: usize) -> Option<(SyllableKey, u8, usize)> {
        (1..=max_len).rev().find_map(|len| {
            let (key, tone) = self.parse_one_key(&input[..len])?;
            Some((key, tone, len))
        })
    }

    fn parse_one_key(&self, input: &[u8]) -> Option<(SyllableKey, u8)> {
        match *self {
            Self::Simple {
                tables,
                use_tone,
                options,
                force_tone,
            } => {
                let (key, tone) = parse_one_zhuyin_key(input, use_tone, options, tables)?;
                if use_tone && force_tone && tone == CHEWING_ZERO_TONE {
                    return None;
                }
                Some((key, tone))
            }
            Self::Discrete {
                tables,
                use_tone,
                options,
                force_tone,
            } => {
                let (key, tone) = parse_one_discrete_key(input, use_tone, options, tables)?;
                if force_tone && tone == CHEWING_ZERO_TONE {
                    return None;
                }
                Some((key, tone))
            }
            Self::Cp26 {
                tables,
                use_tone,
                options,
                force_tone,
            } => {
                let (key, tone) = parse_one_cp26_key(input, use_tone, options, tables)?;
                if use_tone && force_tone && tone == CHEWING_ZERO_TONE {
                    return None;
                }
                Some((key, tone))
            }
        }
    }
}

/// The `ZhuyinParser::parse_one_key` body, split out of the impl so the
/// keyboard dispatch can borrow the [`Keyboard`] probe per family.
fn zhuyin_parse_one_key(
    scheme: ZhuyinScheme,
    options: OptionBits,
    input: &[u8],
) -> Option<ChewingKey> {
    let options = options - OptionBits::PINYIN_AMB_ALL;
    let use_tone = options.contains(OptionBits::USE_TONE);
    let force_tone = options.contains(OptionBits::FORCE_TONE);
    // The probe takes this path's own option word, not the batch parse's.
    let probe = match scheme.keyboard()? {
        Keyboard::Simple(tables) => KeyProbe::Simple {
            tables,
            use_tone,
            options,
            force_tone,
        },
        Keyboard::Discrete(tables) => KeyProbe::Discrete {
            tables,
            use_tone,
            options,
            force_tone,
        },
        Keyboard::Cp26(tables) => KeyProbe::Cp26 {
            tables,
            use_tone,
            options,
            force_tone,
        },
    };
    let (syllable, tone) = probe.parse_one_key(input)?;
    Some(ChewingKey::from_pinyin(syllable.text())?.with_tone(tone))
}

impl Default for ZhuyinParser {
    fn default() -> Self {
        Self::new()
    }
}

fn parse_one_zhuyin_key(
    input: &[u8],
    use_tone: bool,
    options: OptionBits,
    tables: SimpleTables,
) -> Option<(SyllableKey, u8)> {
    let mut symbol_len = input.len();
    let mut tone = 0;
    if use_tone
        && symbol_len > 0
        && let Some(value) = tables.tone(input[symbol_len - 1])
    {
        tone = value;
        symbol_len -= 1;
    }
    if symbol_len == 0 {
        return None;
    }

    let mut zhuyin = String::new();
    for byte in &input[..symbol_len] {
        let symbol = tables.symbol(*byte)?;
        zhuyin.push_str(symbol);
    }
    let key = search_zhuyin_index(tables.index, &zhuyin, options)?;
    Some((key, tone))
}

/// `ZhuyinDiscreteParser2::parse_one_key`
/// (`src/storage/zhuyin_parser2.cpp:335-405`): probe position 0 in the
/// initial table, position 1 in the middle table, position 2 in the final
/// table, position 3 (under `USE_TONE`) in the tone table — a failed
/// initial probe lets the middle probe read position 0, so zero-initial
/// spellings work — then require the whole input consumed and a row hit
/// in the keyboard's index. Each probe takes the **first** matching row,
/// so a dual-mapped key (Hsu `c` → ㄒ/ㄕ) always contributes its first
/// symbol to a parse; the second mapping is display-only.
fn parse_one_discrete_key(
    input: &[u8],
    use_tone: bool,
    options: OptionBits,
    tables: DiscreteTables,
) -> Option<(SyllableKey, u8)> {
    if input.is_empty() {
        return None;
    }

    let mut index = 0;
    let mut initial = "";
    let mut middle = "";
    let mut final_ = "";
    let mut tone = 0;

    // probe initial
    if let Some(symbol) = DiscreteTables::first_symbol(tables.initials, input[index]) {
        initial = symbol;
        index += 1;
    }

    if index != input.len() {
        // probe middle
        if let Some(symbol) = DiscreteTables::first_symbol(tables.middles, input[index]) {
            middle = symbol;
            index += 1;
        }
    }

    if index != input.len() {
        // probe final
        if let Some(symbol) = DiscreteTables::first_symbol(tables.finals, input[index]) {
            final_ = symbol;
            index += 1;
        }
    }

    if index != input.len() && use_tone {
        // probe tone
        if let Some(value) = tables.tone(input[index]) {
            tone = value;
            index += 1;
        }
    }

    if index != input.len() {
        return None;
    }

    let mut zhuyin = String::with_capacity(initial.len() + middle.len() + final_.len());
    zhuyin.push_str(initial);
    zhuyin.push_str(middle);
    zhuyin.push_str(final_);

    let key = search_zhuyin_index(tables.index, &zhuyin, options)?;
    Some((key, tone))
}

/// `ZhuyinDaChenCP26Parser2::parse_one_key`
/// (`src/storage/zhuyin_parser2.cpp:573-716`): the repeat-count probe.
///
/// A run of the same key cycles the symbol rows that key maps to —
/// `count_same_chars` (`:560-573`) counts the run, dual rows pick by
/// `(count - 1) % 2` (1 tap → first row, 2 taps → second, 3 → first…),
/// and the whole run is consumed at once. Three middle keys have
/// multi-way specials instead: `u` cycles `(count - 1) % 3` over
/// middle ㄧ / final ㄚ / both, `m` cycles `(count - 1) % 2` over middle
/// ㄩ / final ㄡ, and `j` is always middle ㄨ. Under `USE_TONE` the
/// **last** input byte is probed in the tone table first and stripped,
/// so keys that are both initial and tone (`e` ㄍ/2, `r` ㄐ/3, `d` ㄎ/4,
/// `y` ㄗ/5) resolve by position. The probe requires the whole input
/// consumed and a hit in the **global** index — which, with no
/// correction bit or'd in, means the plain rows only.
///
/// Live vs display-only: every table row is parse-live (both rows of a
/// dual cycle by repeat count); the one display-only string is the
/// `i` key's extra "ㄧㄚ" in `in_chewing_scheme` — parse can produce
/// ㄧㄚ only through the `u` triple-tap. The upstream `#if 0`
/// partial-input block (`:752-785`) is dead code at the pin and is not
/// ported.
/// `count_same_chars` (`:560-573`): the length of the run of `input[0]`
/// (always ≥ 1).
fn count_same_chars(input: &[u8]) -> usize {
    input.iter().take_while(|&&byte| byte == input[0]).count()
}

/// The CP26 symbol of the run of one key at the start of `run`, and the
/// run's length: a run cycles a dual key's two rows, the first row on an odd
/// length. `None` when `table` does not hold the key.
fn cycled_symbol(
    table: &'static [(u8, &'static str)],
    run: &[u8],
) -> Option<(&'static str, usize)> {
    let count = count_same_chars(run);
    let (first, second) = two_symbols(table, run[0])?;
    let symbol = second.map_or(first, |second| {
        if (count - 1).is_multiple_of(2) {
            first
        } else {
            second
        }
    });
    Some((symbol, count))
}

/// The CP26 middle probe over the run of one key at the start of `run`: the
/// middle, the final that a `u` or `m` special sets, and the bytes consumed.
/// `u`, `m` and `j` have repeat-count specials; the table lookup then
/// validates and consumes the run.
fn cp26_middle(
    middles: &'static [(u8, &'static str)],
    run: &[u8],
) -> (&'static str, &'static str, usize) {
    let mut middle = "";
    let mut final_ = "";
    let count = count_same_chars(run);
    let byte = run[0];
    if byte == b'u' {
        match (count - 1) % 3 {
            0 => middle = "ㄧ",
            1 => final_ = "ㄚ",
            _ => {
                middle = "ㄧ";
                final_ = "ㄚ";
            }
        }
    }
    if byte == b'm' {
        if (count - 1).is_multiple_of(2) {
            middle = "ㄩ";
        } else {
            final_ = "ㄡ";
        }
    }
    if byte == b'j' {
        middle = "ㄨ";
    }
    let consumed = if two_symbols(middles, byte).is_some() {
        count
    } else {
        0
    };
    (middle, final_, consumed)
}

fn parse_one_cp26_key(
    input: &[u8],
    use_tone: bool,
    options: OptionBits,
    tables: Cp26Tables,
) -> Option<(SyllableKey, u8)> {
    if input.is_empty() {
        return None;
    }

    let mut len = input.len();
    let mut tone = 0;
    if use_tone && let Some(value) = tables.tone(input[len - 1]) {
        tone = value;
        len -= 1;
    }
    if len == 0 {
        return None;
    }
    let input = &input[..len];

    let mut index = 0;
    let mut initial = "";
    let mut middle = "";
    let mut final_ = "";

    // probe initial
    if let Some((symbol, count)) = cycled_symbol(tables.initials, &input[index..]) {
        index += count;
        initial = symbol;
    }

    if index != len {
        // probe middle
        let consumed;
        (middle, final_, consumed) = cp26_middle(tables.middles, &input[index..]);
        index += consumed;
    }

    if index != len && final_.is_empty() {
        // probe final (skipped when a u/m special already set it)
        if let Some((symbol, count)) = cycled_symbol(tables.finals, &input[index..]) {
            index += count;
            final_ = symbol;
        }
    }

    if index != len {
        return None;
    }

    let mut zhuyin = String::with_capacity(initial.len() + middle.len() + final_.len());
    zhuyin.push_str(initial);
    zhuyin.push_str(middle);
    zhuyin.push_str(final_);
    let key = search_zhuyin_index(crate::zhuyin_map::zhuyin_pinyin_map(), &zhuyin, options)?;
    Some((key, tone))
}

/// `search_chewing_symbols2` (`zhuyin_parser2.cpp:131-157`): the first
/// and second rows a key maps to in `table` (at most two, table order).
fn two_symbols(
    table: &'static [(u8, &'static str)],
    byte: u8,
) -> Option<(&'static str, Option<&'static str>)> {
    let mut hits = table
        .iter()
        .filter(|(key, _)| *key == byte)
        .map(|(_, s)| *s);
    let first = hits.next()?;
    Some((first, hits.next()))
}

/// `_ChewingKey::is_valid_zhuyin` (`src/storage/chewing_key.cpp:38-45`).
fn is_valid_zhuyin(key: SyllableKey, tone: u8) -> bool {
    let index = key.index();
    let Some(&mask) = VALID_ZHUYIN_TONES.get(index) else {
        return false;
    };
    let Some(bit) = (1u8).checked_shl(u32::from(tone)) else {
        return false;
    };
    mask & bit != 0
}

